  "pl.saveErr": "Не сохранено",
  "pl.ab.title": "Как работает тест",
  "pl.ab.lead": "",
  "pl.ab.what": "Что проверяет",
  "pl.ab.whatText": "Пять навыков: грамматику и лексику, чтение, аудирование, письмо и говорение. Шкала из 9 ступеней — та же, что в маршруте.",
  "pl.ab.how": "Как подбирает задания",
  "pl.ab.howText": "Сначала быстро находит уровень по заданиям из разных тем вперемешку: с лёгкой разминки, шагами через уровень. Потом подробно проверяет этот уровень — по 3 задания на каждую группу тем. Ошибся с уровнем — сам перейдёт ниже или выше.",
  "pl.ab.who": "Кто оценивает",
  "pl.ab.whoText": "Грамматику, лексику, чтение и аудирование — система. Письмо и говорение — вы, по критериям Cambridge и CEFR. Итог выбираете вы.",
  "pl.ab.get": "Что вы получаете",
  "pl.ab.getText": "Карту тем: что ученик знает, что в основном, где зоны роста. Проценты по навыкам, время ответов, записи говорения.",
  "pl.ab.ladder": "Пример: как тест находит уровень",
  "pl.ab.warm": "разминка",
  "pl.ab.result": "B1 по всем темам → итог B1+",
  "pl.ab.right": "верно",
  "pl.ab.wrong": "ошибка",
  "pl.ab.ladderHint": "По 3 задания на уровень: B1 ✓, B2 ✗ → дальше много заданий уровня B1 по всем темам: простые решены — B1, сложные тоже — B1+.",
  "pl.ab.tips": "Как лучше использовать",
  "pl.ab.tip1": "Назначайте до первого урока — и приходите на него уже с планом.",
  "pl.ab.tip2": "Если примерно знаете уровень, отметьте его при назначении — тест будет короче.",
  "pl.ab.tip3": "Результат открывайте ученику после проверки, лучше — вместе на уроке.",
  "pl.ab.tip4": "На разборе аудирования открывайте скрипт «глазиком» — ученик увидит его у себя.",
  "pl.allAnswered": "На все вопросы есть ответ",
