  "pl.exFinal": "Подсказка итога — {h} (середина по всем навыкам). Если письмо и говорение заметно сильнее остального, можно на ступень выше; слабее — ниже.",
  "pl.exNeedWS": "Пока без письма и говорения подсказка — {h}. Оцените их по критериям ниже, и подсказка уточнится.",
  "pl.howRead": "Как читать таблицу",
  "pl.howReadText": "Проценты — доля верных ответов на заданиях уровня. На уровне подробной проверки простые задания показывают сам уровень X, сложные — X+. Карта тем: 3 из 3 — владеет, 2 из 3 — в основном, 0–1 из 3 — зона роста.",
  "pl.expect": "Ожидаемый уровень",
  "pl.expNone": "Не знаю — начать с разминки",
  "pl.expA1": "Начинающий (A1–A2)",
  "pl.expB1": "Средний (B1)",
  "pl.expB2": "Продвинутый (B2–C1)",
  "pl.expectHint": "Совет: если выбрать уровень, тест пропустит часть разминки и начнёт сразу с него — так немного быстрее. Подводный камень: если уровень завышен, ученик сразу встретит трудные задания, а если занижен — тест потратит время на подъём. Самый объективный результат даёт полная версия: «Не знаю — начать с разминки».",
  "pl.extraText": "Результат пока неоднозначный. Чтобы уточнить его, сделайте ещё один текст — он последний в этом разделе.",
