  "pl.ab2.t5": "Заметили неточность в задании — нажмите «На проверку» прямо в тесте или в разборе ответов.",
  "pl.selfAsk": "У вас есть незаконченный тест ({d}). Продолжить с того места, где вы остановились, или начать заново? При новом начале незаконченный тест удалится.",
  "pl.selfContinue": "Продолжить",
  "pl.selfNew": "Начать заново",
  "pl.ab3.grammar": "Грамматика · 13–17 минут",
  "pl.ab3.s1": "1. Разминка",
  "pl.ab3.s1a": "3 лёгких задания: A1, A2, A2.",
  "pl.ab3.s1b": "Если при назначении указан ожидаемый уровень, разминки нет — тест начинается сразу с него.",
  "pl.ab3.s2": "2. Лесенка: поиск уровня",
  "pl.ab3.s2a": "На уровне даются 3 задания — из трёх разных групп тем, вперемешку: одна трудная тема не решает за весь уровень.",
  "pl.ab3.s2b": "2–3 из 3 верно — шаг на уровень выше, 0–1 из 3 — шаг вниз. Если на уровне выше 1 из 3 — ученик пограничный (см. ниже).",
  "pl.ab3.s2c": "0–1 верно — шаг на уровень ниже.",
  "pl.ab3.s2d": "Шаги повторяются, пока не найдётся «потолок» — самый высокий уровень, где ученик справляется. Обычно это 2–4 шага.",
  "pl.ab3.s3": "3. Проверка найденного уровня",
  "pl.ab3.s3a": "По 3 задания на каждую грамматическую тему уровня: 1 простое и 2 сложных.",
  "pl.ab3.s3b": "Простые решены на 60% и больше — уровень подтверждён (B1). Сложные на 67% и больше — уровень с плюсом (B1+).",
  "pl.ab3.s3c": "Ошибка перепроверяется: через несколько заданий даётся ещё одно на ту же тему — так видно, случайность это или пробел.",
  "pl.ab3.s3d": "Темы, где меньше 2 ответов или результат спорный (1 из 2), добираются дополнительными заданиями.",
  "pl.ab3.s3e": "Меньше 40% верных — тест спускается на уровень ниже и проверяет его.",
  "pl.ab3.s3f": "80% и больше — 8 пробных заданий уровня выше: при 70%+ тест проверяет и его. При 55–70% (или 1 из 3 на уровне выше при поиске) ученик пограничный: уровень проверяется полностью, а потом серией даются задания уровнем выше по разделам — раздел без ошибок — 2, с одной ошибкой — 1 (верно — ещё 1). По ним: 70%+ — подробная проверка уровня выше, 55–70% — уровень с плюсом.",
  "pl.ab3.s4": "4. Лексика · 6–8 минут",
  "pl.ab3.s4a": "По одному заданию каждого вида уровнем ниже — проверка базы. Виды: слова по темам, сочетаемость и фразовые глаголы, словообразование, похожие слова, идиомы (с B1).",
  "pl.ab3.s4b": "По 2 задания каждого вида на уровне, который показала грамматика.",
  "pl.ab3.s4c": "70% и больше — по одному заданию каждого вида уровнем выше.",
  "pl.ab3.s4d": "Меньше 40% — ещё 6 заданий уровнем ниже.",
  "pl.ab3.s5": "5. Чтение и аудирование · по 8 минут",
  "pl.ab3.s5a": "Один текст (запись) на 5–6 вопросов на уровне грамматики.",
  "pl.ab3.s5b": "85% и больше — следующий текст уровнем выше, меньше 50% — уровнем ниже, между ними — ещё один того же уровня.",
  "pl.ab3.s5c": "Не больше 3 текстов. Запись можно прослушать дважды.",
  "pl.ab3.s6": "6. Письмо и говорение · 15 минут",
  "pl.ab3.s6a": "Открываются после чтения и аудирования.",
  "pl.ab3.s6b": "Уровень задания — средний из трёх навыков: для письма грамматика, лексика и чтение, для говорения — грамматика, лексика и аудирование.",
  "pl.ab3.s6c": "Вы ставите 0–3 балла по 4 критериям из шкал международных экзаменов (Cambridge, CEFR) — они расписаны для каждого уровня.",
  "pl.ab3.s6d": "Задание оказалось лёгким или сложным — даёте одно дополнительное уровнем выше или ниже; для говорения есть вопросы, чтобы проверить на уроке.",
  "pl.ab3.laneE": "простые → B1 ✓",
  "pl.ab3.laneH": "сложные → B1+ ✓",
  "pl.ab3.result": "итог: B1+",
  "pl.ab3.rep": "перепроверка после ошибки",
  "pl.ab3.chart": "В зоне проверки нижний ряд — простые задания уровня B1, верхний — сложные (B1+). Простые решены — уровень B1 подтверждён, сложные тоже — итог B1+. Кружки — повторная проверка тем, где были ошибки.",
  "pl.ab3.w1": "Уровень подтверждается десятками заданий по разным темам, а не одним удачным ответом; ошибки перепроверяются.",
  "pl.ab3.w2": "Тест сам поправляет себя: если уровень найден неверно, он спустится или поднимется. «I don't know» вместо угадывания не завышает результат.",
  "upd.text": "Платформа обновилась. Обновите страницу, чтобы всё работало как надо — несохранённое на этой странице может потеряться.",
  "upd.reload": "Обновить",
  "upd.later": "Позже",
