  "plt.err.net": "Не получилось сохранить. Проверь интернет и попробуй ещё раз.",
  "plt.lockedWS": "Откроется после чтения и аудирования — задание подберём по твоим результатам",
  "plt.saved": "Ответы сохраняются сразу — можно выйти в любой момент и продолжить с того же места.",
  "plt.pausedGuest": "Можно закрыть страницу. Чтобы продолжить, открой ту же ссылку в этом же браузере.",
  "plt.coreLocked": "Ответы сохранены. К этому разделу вернуться уже нельзя: задания в нём подбирались по твоим ответам. Дальше разделы можно проходить в любом порядке.",
  "plt.partLocked": "Ответы сохранены, этот раздел закрыт. Остальные разделы можно проходить в любом порядке — переключайся вверху.",
  "plt.introLead": "Шесть коротких разделов, примерно 25–40 минут. Отвечай сам, без словаря и переводчика — так преподаватель поймёт, с чего тебе лучше начать.",
  "plt.rule2": "Не знаешь ответ — выбери «I don't know». Это лучше, чем угадывать.",
