  "plt.dkTip": "Не уверен в ответе? Лучше выбери этот вариант, чем угадывать, — так тест точнее определит твой уровень.",
  "plt.dkSlow": "Думаешь уже давно? Если не уверен, лучше выбери «I don't know», чем угадывать, — так уровень определится точнее.",
  "plt.bracketsHint": "Впиши нужную форму слова из скобок. Если нужно, добавь служебные слова. Краткие и полные формы засчитываются одинаково. Пример: I ___ (not / forget) your birthday → won't forget или will not forget.",
