  "pl.welTitle": "Пара слов перед началом",
  "pl.welDk": "Не знаете ответ — смело нажимайте «I don't know». Это не ошибка и никто не осудит: так тест быстрее и точнее найдёт ваш уровень.",
  "pl.welGoogle": "Не ищите ответы в интернете и не пользуйтесь переводчиком. Идеальный ответ не нужен — нужен ваш. Иначе тест станет длиннее, а результат — неточным, и заниматься будет сложнее.",
  "pl.welMist": "Ошибки — это нормально. Все ответы вы потом разберёте с преподавателем.",
  "pl.welPause": "Устали — остановитесь. Ответы сохраняются сразу, продолжить можно позже с того же места.",
  "pl.welOk": "Понятно, начинаем",
  "pl.tiredTip": "Устали? Можно сделать перерыв — ответы уже сохранены.",
  "plt.welTitle": "Привет! Пара слов перед началом",
  "plt.welDk": "Не знаешь ответ — смело жми «I don't know». Никто тебя не осудит: это честнее, чем угадывать, и тест быстрее найдёт твой уровень.",
  "plt.welGoogle": "Не гугли и не пользуйся переводчиком. Идеальный ответ не нужен — нужен твой. Иначе тест станет длиннее, а результат — неточным. Это не в твоих интересах.",
  "plt.welMist": "Ошибаться — нормально. Все ответы ты потом разберёшь с учителем.",
  "plt.welPause": "Устал — остановись. Ответы сохраняются сразу, продолжить можно позже с того же места.",
  "plt.welOk": "Понятно, начинаем!",
  "plt.tiredTip": "Устал? Можно сделать перерыв — ответы уже сохранены.",
  "plt.factTime": "25–40 минут",
  "pl.scRemind": "Задание уровня {l} — критерии и баллы ниже даны для этого уровня, как в {ex}. Оцените каждый критерий от 0 до {max}: {how}",
  "nt.take": "Пройти тест",
  "pl.linkS1": "Создайте ссылку и скопируйте её.",
  "pl.linkS2": "Отправьте её человеку, у которого ещё нет аккаунта на платформе, — в мессенджер или на почту.",
  "pl.linkS3": "Он вводит имя и контакт и проходит тест. Прерваться можно в любой момент: продолжить — по той же ссылке в том же браузере.",
  "pl.linkS4": "Когда он закончит, вам придёт уведомление, а результат появится в «Результатах» на этой вкладке. Письмо и говорение проверяете вы.",
  "pl.howTitle": "Как это работает",
  "pl.assignS1": "Выберите ученика и, если нужно, версию теста.",
  "pl.assignS2": "Ученик получит уведомление со ссылкой «Пройти тест», а в его кабинете появится карточка «Placement test».",
  "pl.assignS3": "Он проходит тест в своём кабинете; прерваться можно в любой момент — ответы сохраняются.",
  "pl.assignS4": "Когда ученик закончит, вам придёт уведомление. Проверьте письмо и говорение и утвердите уровень — после этого ученик увидит результат.",
  "pl.assignTip": "Если у ученика уже есть незаконченный тест, он заменится новым.",
  "pl.factTimeBoth": "Adults 40–60 мин · Teens 25–40 мин",
