  "rp.leadStudent": "Отчёт для ученика: уровень по навыкам, сильные стороны, над чем работать, грамматика по разделам, письмо и рекомендации. Его можно скачать в PDF и отправить в кабинет ученика. Разбор ответов — отдельным PDF на вкладке «Разбор ответов».",
