  "pl.ab.title": "How the test works",
  "pl.ab.lead": "",
  "pl.ab.what": "What it checks",
  "pl.ab.whatText": "Five skills: grammar and vocabulary, reading, listening, writing and speaking. A 9-step scale, the same as in the route.",
  "pl.ab.how": "How it picks questions",
  "pl.ab.howText": "First it quickly finds the level with mixed questions from different topics, from a light warm-up in level-sized steps. Then it checks that level in depth — 3 questions per topic group. If the level was wrong, it moves down or up by itself.",
  "pl.ab.who": "Who marks it",
  "pl.ab.whoText": "The system marks grammar, vocabulary, reading and listening. You mark writing and speaking by Cambridge/CEFR criteria and choose the result.",
  "pl.ab.get": "What you get",
  "pl.ab.getText": "A topic map: what the student knows, mostly knows and needs to work on. Skill percentages, answer times, speaking recordings.",
  "pl.ab.ladder": "Example: how the test finds the level",
  "pl.ab.warm": "warm-up",
  "pl.ab.result": "B1 across all topics → result B1+",
  "pl.ab.right": "right",
  "pl.ab.wrong": "mistake",
  "pl.ab.ladderHint": "3 questions per level: B1 ✓, B2 ✗ → then many B1 questions across all topics: easy ones right — B1, hard ones too — B1+.",
  "pl.ab.tips": "Best practice",
  "pl.ab.tip1": "Assign it before the first lesson and come with a plan.",
  "pl.ab.tip2": "If you roughly know the level, mark it when assigning — the test gets shorter.",
  "pl.ab.tip3": "Open the result to the student after checking, ideally together in class.",
  "pl.ab.tip4": "When reviewing listening, open the script with the eye — the student sees it too.",
  "pl.allAnswered": "All questions answered",
  "pl.leftQ": "Unanswered: {n}",
  "pl.backToTest": "Back to the test",
  "pl.exitNow": "Exit",
  "pl.coreLocked": "Answers are saved. You can't return to this part: its questions depended on your answers. The other parts can be done in any order.",
  "pl.partLocked": "Answers are saved and this part is closed. Do the others in any order — switch at the top.",
  "pl.partDone": "“{part}” is done",
  "pl.nextPart": "Next",
  "pl.goOn": "Continue",
  "pl.coreProgress": "Progress in this part",
  "pl.dontKnow": "I don't know",
  "pl.dkCount": "“I don't know”: {n} {n:time|times}",
  "pl.exTitle": "System summary",
  "pl.exCore": "Grammar and vocabulary: confident up to {r}.",
  "pl.exNext": "The next step {s} isn't confirmed ({c} of {n}).",
  "pl.exTop": "This is the top of the scale.",
  "pl.exLow": "Grammar and vocabulary: the basic level isn't confirmed yet — A1.",
  "pl.exSkill": "{s}: {p}% at {l}, that is {r}.",
  "pl.exFinal": "Suggested result: {h} (the middle of all skills). If writing and speaking are clearly stronger, go one step up; weaker — one down.",
  "pl.exNeedWS": "Without writing and speaking the hint is {h}. Mark them below to refine it.",
  "pl.howRead": "How to read the table",
  "pl.howReadText": "Percent = share of right answers at that level. At the checked level, easier items show level X and harder ones X+. Topic map: 3/3 solid, 2/3 mostly, 0–1/3 to work on.",
  "pl.expect": "Expected level",
  "pl.expNone": "Not sure — start with a warm-up",
  "pl.expA1": "Beginner (A1–A2)",
  "pl.expB1": "Intermediate (B1)",
  "pl.expB2": "Advanced (B2–C1)",
  "pl.expectHint": "Tip: choosing a level skips part of the warm-up and starts there — a little faster. The catch: if the level is too high, the student meets hard questions straight away; if too low, the test spends time climbing. The most objective result comes from the full version: “Not sure — start with the warm-up”.",
  "pl.extraText": "The result isn't clear yet. Do one more text to confirm it — it's the last one in this part.",
