  "pl.borderHint": "The level above was not passed but not failed either (1 of 3 when locating the level, or 55–70% on the sample). First the level is checked in full, then a series of tasks one level up, by section: a section with no mistakes gets 2, with one mistake — 1 (if right — one more). 70%+ on them — a full check of the level above, 55–70% — a “plus”.",
