  "pl.warnRec": "Recording {n} has unanswered questions. Answer them — or press “Finish this part” again.",
  "pl.th1": "Adapts to the student.",
  "pl.th1b": "Each next question depends on the answers — no time wasted on too easy or too hard ones.",
  "pl.th2": "A ladder: level first, then topics.",
  "pl.th2b": "It finds the boundary in level-sized steps, then checks that level with 3 questions per topic.",
  "pl.th3": "The rest is at the found level.",
  "pl.th3b": "Reading, listening, writing and speaking confirm the result. You mark writing and speaking.",
  "pl.more": "How the test works — in detail",
  "pl.ab.blocks": "What's inside",
  "pl.ab.b.core": "Warm-up, level search (mixed topics), then 33–36 questions at that level — 3 per topic group. Answers can be fixed within the part.",
  "pl.ab.b.reading": "Two texts at the student's level, 3–4 questions each. Under half right — one more text a level lower.",
  "pl.ab.b.listening": "Two British or American recordings, two plays each. A backup recording by the same rule.",
  "pl.ab.b.writing": "A short text for a level task. You tick covered points and score 0–3 on 4 criteria.",
  "pl.ab.b.speaking": "2–3 spoken questions, prep time and a recorded answer. Students can play back and re-record.",
  "pl.part.vocab": "Vocabulary",
  "pl.partHint.vocab": "Words, collocations and word formation — adapts to your answers",
  "pl.partTime.vocab": "≈ 6–8 minutes",
  "pl.hintShow": "Hint",
  "pl.withHint": "with hint",
  "pl.exVocab": "Vocabulary: {p} → {r}.",
  "pl.vmapTitle": "Vocabulary · {l}",
  "pl.st1": "Start screen",
  "pl.st1t": "The student sees the parts, checks sound and microphone. Answers save instantly — breaks are fine.",
  "pl.st2": "Grammar: ladder and full check",
  "pl.st2t": "Warm-up (A1, A2), then a level search: 3 easy questions per level from three different topic groups, 2 of 3 — one level up (1 of 3 on the level above — borderline). The found level is checked across all topic groups, 3 questions each (1 easy, 2 harder). Under 40% after 9 — down a level; 80%+ — a sample of the level above; 55–70% there — borderline: every section is checked one level up too. Easy items show level X, harder ones X+.",
  "pl.st3": "Vocabulary: a short ladder",
  "pl.st3t": "Checks the level shown by grammar. First 2 questions a level lower — prepositions and word formation, to see if the base is solid. Then 2 questions of each kind: topic words, collocations and phrasal verbs, word formation, confusable words, idioms (from B1). 70%+ — questions a level higher; below 40% — 6 questions a level lower (the warm-up counts too). 10–18 questions in total.",
  "pl.st4": "Reading and listening",
  "pl.st4t": "2 texts and 2 recordings at the lower of the grammar and vocabulary levels. Under 50% — one more a level lower, 85%+ — a level higher. Each recording plays twice. Parts can be done in any order.",
  "pl.st5": "Writing and speaking",
  "pl.st5t": "Tasks at the student's level. You tick covered points and score 0–3 on four criteria — the system turns scores into a sublevel.",
  "pl.st6": "Result and point A",
  "pl.st6t": "Skills table, topic map with gaps, answer times and a system summary. You choose the final level — it becomes point A. The result opens to the student with a switch; scripts — with the eye.",
  "pl.allLevels": "All levels",
  "pl.theme": "Topic",
  "pl.allThemes": "All topics ({n})",
  "pl.bankSearch": "Search by topic or text",
  "pl.found": "Found: {n}",
  "pl.famTitle": "Grammar by area",
  "pl.famLegend": "right answers",
  "pl.famCol": "Area",
  "pl.famAt": "At {l}",
  "pl.famAll": "All",
  "pl.exForms": "Grammar by task type: choice {a}, typed {b}. If typing is clearly weaker, the student recognises the rule but doesn't yet use it.",
  "pl.exRepeats": "Re-check after a mistake ({n}): confirmed in {k}. {list}",
  "pl.nextLeft": "{n} unanswered — they count as wrong, and you can't come back. Continue?",
  "pl.byPrev": "chosen from your answers",
  "pl.dkTip": "Not sure? Choose this instead of guessing — it helps the test find your level more accurately.",
  "pl.factAny": "Universal — for any level",
  "pl.linkTip": "Several people can use one link. Close it when you're done — the old link will no longer start a test.",
  "pl.ab2.how": "How the test finds the level",
  "pl.ab2.s1": "Start",
  "pl.ab2.s1t": "3 easy warm-up questions. If you set an expected level, it starts there.",
  "pl.ab2.s2": "Ladder",
  "pl.ab2.s2t": "3 key questions per level: 2 of 3 right — a step up, fewer — a step down. That's how it finds the ceiling.",
  "pl.ab2.s3": "Check",
  "pl.ab2.s3t": "The level found is checked across all topics — most questions are here. Easy ones right — the level is there; hard ones too — a “plus” (B1+). Mistakes are re-checked and thin topics get more questions. Fails — it goes down; easy — it tries a level up.",
  "pl.ab2.parts": "What's inside",
  "pl.ab2.p.core": "Grammar · 13–17 min — the ladder above; every big area (tenses, conditionals, verb patterns…) gets at least 2 answers.",
  "pl.ab2.p.vocab": "Vocabulary · 6–8 min — first one question of each type a level lower (the base), then the grammar level: did well — harder, weak — easier.",
  "pl.ab2.p.texts": "Reading and listening · 8 min each — one text with 5–6 questions. 85%+ — the next text is a level up, under 50% — down, in between — one more at the same level. Up to 3 texts.",
  "pl.ab2.p.ws": "Writing and speaking · 15 min — open after reading and listening. The task level is the middle of three skills: grammar, vocabulary and reading for writing; grammar, vocabulary and listening for speaking. You give 0–3 for 4 criteria from international exam scales (Cambridge, CEFR); if the task was too easy or too hard, you give one extra task a level up or down.",
  "pl.ab2.read": "How to read the result",
  "pl.ab2.r1": "A level per skill and a suggested overall level. You choose the final level — it becomes point A of the route.",
  "pl.ab2.r2": "Topic map: what the student knows, what's partial, where to grow — a ready list for the first lessons.",
  "pl.ab2.r3": "“Recognises vs uses”: if typing answers is weaker than choosing — the rule is known only passively.",
  "pl.ab2.r4": "Answer times: very fast answers are highlighted — the student may have guessed. Answers with a hint are only marked and don't affect the level.",
  "pl.ab2.why": "Why you can trust the result",
  "pl.ab2.w1": "A level is confirmed by many questions on different topics, not one lucky answer.",
  "pl.ab2.w2": "The test corrects itself: if the level was wrong, it goes down or up.",
  "pl.ab2.w3": "A random slip is re-checked, and “I don't know” instead of guessing keeps the result honest — if the student hesitates, the test reminds them of it.",
  "pl.ab2.w4": "It can be retaken — questions barely repeat.",
  "pl.ab2.tips": "How to use it best",
  "pl.ab2.t1": "Assign it before the first lesson and come with a plan.",
  "pl.ab2.t2": "Ask the student to set aside 40–60 quiet minutes and not use a dictionary or translator.",
  "pl.ab2.t3": "If you roughly know the level, set it when assigning — the test is a bit shorter.",
  "pl.ab2.t4": "Show the result after you've checked writing and speaking — ideally together in a lesson.",
  "pl.lockedWS": "Opens after reading and listening — the task is chosen from your results",
