  "pl.ab3.grammar": "Grammar · 13–17 minutes",
  "pl.ab3.s1": "1. Warm-up",
  "pl.ab3.s1a": "3 easy questions: A1, A2, A2.",
  "pl.ab3.s1b": "If an expected level is set, there's no warm-up — the test starts at that level.",
  "pl.ab3.s2": "2. Ladder: finding the level",
  "pl.ab3.s2a": "3 questions are given at a level — from three different topic groups, mixed, so one hard topic does not decide the level.",
  "pl.ab3.s2b": "2–3 of 3 right — one level up, 0–1 of 3 — one level down. 1 of 3 on the level above — the student is borderline (see below).",
  "pl.ab3.s2c": "0–1 right — one level down.",
  "pl.ab3.s2d": "Steps repeat until the ceiling is found — the highest level the student copes with. Usually 2–4 steps.",
  "pl.ab3.s3": "3. Checking the level found",
  "pl.ab3.s3a": "3 questions per grammar topic of the level: 1 easy and 2 hard.",
  "pl.ab3.s3b": "Easy ones 60%+ right — the level is confirmed (B1). Hard ones 67%+ — a plus level (B1+).",
  "pl.ab3.s3c": "A mistake is re-checked: a few questions later another one on the same topic shows whether it was a slip or a gap.",
  "pl.ab3.s3d": "Topics with fewer than 2 answers or a split result (1 of 2) get extra questions.",
  "pl.ab3.s3e": "Under 40% right — the test goes a level down and checks it.",
  "pl.ab3.s3f": "80%+ — 8 sample questions of the next level: 70%+ there and it checks that level too. 55–70% (or 1 of 3 on the level above in the search) — borderline: the level is checked in full, then a series of questions one level up by section — no mistakes: 2, one mistake: 1 (if right — one more). On these: 70%+ — full check of the level above, 55–70% — a plus level.",
  "pl.ab3.s4": "4. Vocabulary · 6–8 minutes",
  "pl.ab3.s4a": "One question of each type a level lower — the base. Types: topic words, collocations and phrasal verbs, word formation, confusable words, idioms (from B1).",
  "pl.ab3.s4b": "2 questions of each type at the level grammar showed.",
  "pl.ab3.s4c": "70%+ — one question of each type a level up.",
  "pl.ab3.s4d": "Under 40% — 6 more questions a level down.",
  "pl.ab3.s5": "5. Reading and listening · 8 minutes each",
  "pl.ab3.s5a": "One text (recording) with 5–6 questions at the grammar level.",
  "pl.ab3.s5b": "85%+ — the next text is a level up, under 50% — a level down, in between — one more at the same level.",
  "pl.ab3.s5c": "Up to 3 texts. A recording can be played twice.",
  "pl.ab3.s6": "6. Writing and speaking · 15 minutes",
  "pl.ab3.s6a": "Open after reading and listening.",
  "pl.ab3.s6b": "Task level — the middle of three skills: grammar, vocabulary and reading for writing; grammar, vocabulary and listening for speaking.",
  "pl.ab3.s6c": "You give 0–3 for 4 criteria from international exam scales (Cambridge, CEFR), described for each level.",
  "pl.ab3.s6d": "Task too easy or too hard — give one extra task a level up or down; for speaking there are questions to check in a lesson.",
  "pl.ab3.laneE": "easy → B1 ✓",
  "pl.ab3.laneH": "hard → B1+ ✓",
  "pl.ab3.result": "result: B1+",
  "pl.ab3.rep": "re-check after a mistake",
  "pl.ab3.chart": "In the check zone the lower row is easy B1 questions, the upper row hard ones (B1+). Easy ones right — B1 confirmed, hard ones too — B1+. Rings are re-checks of topics with mistakes.",
  "pl.ab3.w1": "A level is confirmed by dozens of questions on different topics, not one lucky answer; mistakes are re-checked.",
  "pl.ab3.w2": "The test corrects itself: if the level is wrong, it goes down or up. “I don't know” instead of guessing keeps the result honest.",
