  "pl.welTitle": "Before you start",
  "pl.welDk": "Don't know the answer? Press “I don't know”. It isn't a mistake, and it helps the test find your level faster and more accurately.",
  "pl.welGoogle": "Don't search online or use a translator. We don't need a perfect answer — we need yours. Otherwise the test gets longer and the result less accurate.",
  "pl.welMist": "Mistakes are fine. You'll go through all your answers with your teacher later.",
